parameters.functionCode:
// Extract appointment data and hours before
const appointment = $input.first().json.appointment;
const hoursBefore = $input.first().json.metadata?.hoursBefore || 24;
const patientInfo = appointment.patientId || {};

// Prepare reminder data
return {
  patientEmail: patientInfo.email || '',
  patientName: `${patientInfo.firstName || ''} ${patientInfo.lastName || ''}`.trim(),
  patientPhone: patientInfo.phone || '',
  doctorName: appointment.doctorName || 'Your Doctor',
  appointmentDate: appointment.date,
  appointmentTime: appointment.time,
  appointmentType: appointment.type || 'checkup',
  location: appointment.location || 'Medical Center',
  isVideoCall: appointment.isVideoCall || false,
  hoursBefore: hoursBefore,
  appointmentId: appointment._id
};

parameters.text:
Dear {{ $node['Prepare Reminder Data'].json.patientName }},

This is a friendly reminder about your upcoming appointment:

Appointment Details:
- Date: {{ $node['Prepare Reminder Data'].json.appointmentDate }}
- Time: {{ $node['Prepare Reminder Data'].json.appointmentTime }}
- Type: {{ $node['Prepare Reminder Data'].json.appointmentType }}
- Doctor: {{ $node['Prepare Reminder Data'].json.doctorName }}
- Location: {{ $node['Prepare Reminder Data'].json.location }}
{% if $node['Prepare Reminder Data'].json.isVideoCall %}
- This is a video call appointment. Please check your email for the meeting link.
{% endif %}

Please remember to:
- Arrive 15 minutes early
- Bring your ID and insurance card
- Bring any relevant medical records
- Take your regular medications unless instructed otherwise

If you need to reschedule or cancel, please call us as soon as possible.

We look forward to seeing you!

MediFollow Team

parameters.functionCode:
// Send SMS reminder if phone number available
const data = $node['Prepare Reminder Data'].json;
if (data.patientPhone) {
  return {
    to: data.patientPhone,
    message: `Reminder: Your appointment with ${data.doctorName} is tomorrow at ${data.appointmentTime}. Reply CANCEL to reschedule.`
  };
}
return null;

// Log completion
const data = $node['Prepare Reminder Data'].json;
return {
  success: true,
  message: 'Appointment reminders sent successfully',
  timestamp: new Date().toISOString(),
  appointmentId: data.appointmentId,
  hoursBefore: data.hoursBefore
};
